import{_ as e,g as o,b as a,a5 as d}from"./chunks/framework.Bm3yuaik.js";const u=JSON.parse('{"title":"Component taxonomy","description":"","frontmatter":{},"headers":[],"relativePath":"guide/component-taxonomy.md","filePath":"guide/component-taxonomy.md"}'),n={name:"guide/component-taxonomy.md"};function i(r,t,c,s,l,p){return o(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="component-taxonomy" tabindex="-1">Component taxonomy <a class="header-anchor" href="#component-taxonomy" aria-label="Permalink to &quot;Component taxonomy&quot;">​</a></h1><p><code>doctui</code> classifies components by stable UI domains instead of roadmap phases. The same taxonomy drives Storybook navigation, documentation discovery, registries, and future MCP tools.</p><h2 id="canonical-categories" tabindex="-1">Canonical categories <a class="header-anchor" href="#canonical-categories" aria-label="Permalink to &quot;Canonical categories&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Label</th><th>Purpose</th></tr></thead><tbody><tr><td><code>layout</code></td><td>Layout</td><td>Structure, spacing, alignment, and responsive layout</td></tr><tr><td><code>typography</code></td><td>Typography</td><td>Semantic text and headings</td></tr><tr><td><code>actions</code></td><td>Actions</td><td>Controls that trigger user actions</td></tr><tr><td><code>inputs</code></td><td>Inputs</td><td>Form controls that collect or edit values</td></tr><tr><td><code>navigation</code></td><td>Navigation</td><td>Moving between views, sections, and destinations</td></tr><tr><td><code>data-display</code></td><td>Data display</td><td>Structured values, status, and information</td></tr><tr><td><code>feedback</code></td><td>Feedback</td><td>Loading, progress, validation, and status feedback</td></tr><tr><td><code>overlays</code></td><td>Overlays</td><td>Dialogs, popovers, menus, and tooltips</td></tr><tr><td><code>media</code></td><td>Media</td><td>Images, icons, avatars, and visual media</td></tr><tr><td><code>utilities</code></td><td>Utilities</td><td>Low-level helpers that support composition</td></tr></tbody></table><p>The machine-readable ID is the contract. Human-facing labels may be presented in Storybook or documentation without requiring MCP clients to parse UI text.</p><h2 id="storybook-mapping" tabindex="-1">Storybook mapping <a class="header-anchor" href="#storybook-mapping" aria-label="Permalink to &quot;Storybook mapping&quot;">​</a></h2><p>Component stories use <code>Category/Component</code> paths:</p><ul><li><code>Layout/Box</code></li><li><code>Layout/Flex</code></li><li><code>Layout/Stack</code></li><li><code>Layout/Group</code></li><li><code>Typography/Text</code></li><li><code>Typography/Title</code></li><li><code>Actions/Button</code></li></ul><p>Cross-component examples live under <code>Recipes/...</code> instead of pretending to be component categories.</p><p>Storybook 10 requires CSF titles and <code>storySort</code> configuration to be statically analyzable, so Storybook keeps literal labels in its source files. Tests compare those literals against the canonical metadata registry so the human navigation cannot silently drift from the machine-readable taxonomy.</p><h2 id="metadata-source" tabindex="-1">Metadata source <a class="header-anchor" href="#metadata-source" aria-label="Permalink to &quot;Metadata source&quot;">​</a></h2><p><code>@doctui/core</code> exports:</p><ul><li><code>DOCTUI_COMPONENT_CATEGORIES</code></li><li><code>DOCTUI_COMPONENT_METADATA</code></li><li><code>getComponentCategory()</code></li><li><code>getComponentMetadata()</code></li><li><code>getComponentStorybookTitle()</code></li></ul><p>Future MCP and registry endpoints should consume these exports rather than maintaining a second machine-readable category list. That keeps Storybook, docs, and machine discovery aligned as the component set grows.</p>',14)])])}const h=e(n,[["render",i]]);export{u as __pageData,h as default};
